process.env.MODO_TESTE = '1';
const request = require('supertest');
const { criarServidor } = require('../src/app');

// Ponto 1 (RN-204 expiração em cadeia) + Ponto 7 (RN-212/213 valor absoluto 2h).
// Origem: entrevistas/M2-inscricoes.mc P3 (recomputo após cancelamento ou expiração)
// e P11 (convocadaAte = instante da liberação + 2h); spec specs/M2-inscricoes.md RN-204/RN-212.
describe('M2-RN-204/212 — expiração em cadeia e prazo absoluto de 2h', () => {
  let app;
  beforeEach(() => { app = criarServidor(); });

  async function criarMini1Vaga(app) {
    const r = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
      titulo: 'Mini 1 vaga', tipo: 'minicurso', salaId: 'lab-3', vagas: 1,
      encontros: [
        { inicio: '2026-10-19T19:00:00-03:00', fim: '2026-10-19T21:00:00-03:00' },
        { inicio: '2026-10-20T19:00:00-03:00', fim: '2026-10-20T21:00:00-03:00' }
      ]
    });
    expect(r.status).toBe(201);
    return r.body.id;
  }

  it('convocadaAte é o instante da liberação + 2h (valor escrito à mão)', async () => {
    await request(app).post('/_teste/reset').expect(204);
    const id = await criarMini1Vaga(app);
    await request(app).put('/_teste/relogio').send({ agora: '2026-10-13T10:00:00-03:00' }).expect(200);
    const a = await request(app).post(`/atividades/${id}/inscricoes`).set('X-Usuario', 'p-carla').expect(201);
    const b = await request(app).post(`/atividades/${id}/inscricoes`).set('X-Usuario', 'p-joao').expect(201);
    expect(b.body.status).toBe('em_espera');
    await request(app).post(`/inscricoes/${a.body.id}/cancelamento`).set('X-Usuario', 'p-carla').expect(200);
    const conv = await request(app).get(`/inscricoes/${b.body.id}`).set('X-Usuario', 'p-joao').expect(200);
    expect(conv.body.status).toBe('convocada');
    // 10:00-03:00 + 2h = 12:00-03:00 = 15:00Z — valor da spec, não lido do código
    expect(conv.body.convocadaAte).toBe('2026-10-13T15:00:00.000Z');
  });

  it('expiração convoca o próximo em cadeia e recomputa posições (1 vaga, A conf, B/C espera)', async () => {
    await request(app).post('/_teste/reset').expect(204);
    const id = await criarMini1Vaga(app);
    await request(app).put('/_teste/relogio').send({ agora: '2026-10-13T10:00:00-03:00' }).expect(200);
    const a = await request(app).post(`/atividades/${id}/inscricoes`).set('X-Usuario', 'p-carla').expect(201);
    const b = await request(app).post(`/atividades/${id}/inscricoes`).set('X-Usuario', 'p-joao').expect(201);
    const c = await request(app).post(`/atividades/${id}/inscricoes`).set('X-Usuario', 'p-diego').expect(201);
    expect(b.body.posicaoNaEspera).toBe(1);
    expect(c.body.posicaoNaEspera).toBe(2);

    // cancela A → B convocada (10:00+2h), C passa a posição 1
    await request(app).post(`/inscricoes/${a.body.id}/cancelamento`).set('X-Usuario', 'p-carla').expect(200);
    const bConv = await request(app).get(`/inscricoes/${b.body.id}`).set('X-Usuario', 'p-joao').expect(200);
    expect(bConv.body.status).toBe('convocada');
    expect(bConv.body.convocadaAte).toBe('2026-10-13T15:00:00.000Z');
    const cEsp = await request(app).get(`/inscricoes/${c.body.id}`).set('X-Usuario', 'p-diego').expect(200);
    expect(cEsp.body.status).toBe('em_espera');
    expect(cEsp.body.posicaoNaEspera).toBe(1);

    // avança além de convocadaAte de B e confirma B → EXPIRADA + C convocada em cadeia
    await request(app).put('/_teste/relogio').send({ agora: '2026-10-13T12:01:00-03:00' }).expect(200);
    const exp = await request(app).post(`/inscricoes/${b.body.id}/confirmacao`).set('X-Usuario', 'p-joao');
    expect(exp.status).toBe(422);
    expect(exp.body.erro).toBe('CONVOCACAO_EXPIRADA');

    const bExp = await request(app).get(`/inscricoes/${b.body.id}`).set('X-Usuario', 'p-joao').expect(200);
    expect(bExp.body.status).toBe('expirada');
    expect(bExp.body.posicaoNaEspera).toBe(null);

    const cConv = await request(app).get(`/inscricoes/${c.body.id}`).set('X-Usuario', 'p-diego').expect(200);
    expect(cConv.body.status).toBe('convocada');
    expect(cConv.body.posicaoNaEspera).toBe(null);
    // 12:01-03:00 + 2h = 14:01-03:00 = 17:01Z
    expect(cConv.body.convocadaAte).toBe('2026-10-13T17:01:00.000Z');
  });
});

process.env.MODO_TESTE = '1';
const request = require('supertest');
const { criarServidor } = require('../src/app');

// Ponto 2 (RN-206): cancelada/expirada permitem nova inscrição.
// Origem: entrevistas/M2-inscricoes.mc P4; spec RN-206.
describe('M2-RN-206 — reinscrição após inativa', () => {
  let app;
  beforeEach(() => { app = criarServidor(); });

  async function criarMini(app, vagas = 20) {
    const r = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
      titulo: 'Mini', tipo: 'minicurso', salaId: 'lab-3', vagas,
      encontros: [
        { inicio: '2026-10-19T19:00:00-03:00', fim: '2026-10-19T21:00:00-03:00' },
        { inicio: '2026-10-20T19:00:00-03:00', fim: '2026-10-20T21:00:00-03:00' }
      ]
    });
    expect(r.status).toBe(201);
    return r.body.id;
  }

  it('reinscreve com 201 após cancelar a inscrição anterior', async () => {
    await request(app).post('/_teste/reset').expect(204);
    const id = await criarMini(app);
    const ins = await request(app).post(`/atividades/${id}/inscricoes`).set('X-Usuario', 'p-carla').expect(201);
    await request(app).post(`/inscricoes/${ins.body.id}/cancelamento`).set('X-Usuario', 'p-carla').expect(200);
    const nova = await request(app).post(`/atividades/${id}/inscricoes`).set('X-Usuario', 'p-carla').expect(201);
    expect(nova.body.status).toBe('confirmada');
  });

  it('reinscreve com 201 após a inscrição expirar', async () => {
    await request(app).post('/_teste/reset').expect(204);
    const id = await criarMini(app, 1);
    await request(app).put('/_teste/relogio').send({ agora: '2026-10-13T10:00:00-03:00' }).expect(200);
    const a = await request(app).post(`/atividades/${id}/inscricoes`).set('X-Usuario', 'p-carla').expect(201);
    const b = await request(app).post(`/atividades/${id}/inscricoes`).set('X-Usuario', 'p-joao').expect(201);
    await request(app).post(`/inscricoes/${a.body.id}/cancelamento`).set('X-Usuario', 'p-carla').expect(200);
    const conv = await request(app).get(`/inscricoes/${b.body.id}`).set('X-Usuario', 'p-joao').expect(200);
    expect(conv.body.status).toBe('convocada');
    await request(app).put('/_teste/relogio').send({ agora: '2026-10-13T12:01:00-03:00' }).expect(200);
    await request(app).post(`/inscricoes/${b.body.id}/confirmacao`).set('X-Usuario', 'p-joao').expect(422);
    const exp = await request(app).get(`/inscricoes/${b.body.id}`).set('X-Usuario', 'p-joao').expect(200);
    expect(exp.body.status).toBe('expirada');
    const nova = await request(app).post(`/atividades/${id}/inscricoes`).set('X-Usuario', 'p-joao').expect(201);
    expect(nova.body.status).toBe('confirmada');
  });
});

process.env.MODO_TESTE = '1';
const request = require('supertest');
const { criarServidor } = require('../src/app');

// Ponto 3 (RN-207): convocada bloqueia; cancelada/expirada não bloqueiam.
// Origem: entrevistas/M2-inscricoes.mc P5; spec RN-207.
describe('M2-RN-207 — convocada conta, cancelada/expirada não contam', () => {
  let app;
  beforeEach(() => { app = criarServidor(); });

  const ENC_A = [
    { inicio: '2026-10-19T19:00:00-03:00', fim: '2026-10-19T21:00:00-03:00' },
    { inicio: '2026-10-20T19:00:00-03:00', fim: '2026-10-20T21:00:00-03:00' }
  ];
  const ENC_B = [
    { inicio: '2026-10-19T20:00:00-03:00', fim: '2026-10-19T22:00:00-03:00' },
    { inicio: '2026-10-21T19:00:00-03:00', fim: '2026-10-21T21:00:00-03:00' }
  ];

  async function criar(app, titulo, salaId, encontros, vagas = 20) {
    const r = await request(app).post('/atividades').set('X-Usuario', 'org-ana')
      .send({ titulo, tipo: 'minicurso', salaId, vagas, encontros });
    expect(r.status).toBe(201);
    return r.body.id;
  }

  it('convocada bloqueia inscrição sobreposta com 409 CONFLITO_DE_HORARIO', async () => {
    await request(app).post('/_teste/reset').expect(204);
    const lotada = await criar(app, 'Lotada', 'lab-3', ENC_A, 1);
    await request(app).put('/_teste/relogio').send({ agora: '2026-10-13T10:00:00-03:00' }).expect(200);
    const conf = await request(app).post(`/atividades/${lotada}/inscricoes`).set('X-Usuario', 'p-carla').expect(201);
    const espera = await request(app).post(`/atividades/${lotada}/inscricoes`).set('X-Usuario', 'p-joao').expect(201);
    await request(app).post(`/inscricoes/${conf.body.id}/cancelamento`).set('X-Usuario', 'p-carla').expect(200);
    const conv = await request(app).get(`/inscricoes/${espera.body.id}`).set('X-Usuario', 'p-joao').expect(200);
    expect(conv.body.status).toBe('convocada');

    const alvo = await criar(app, 'Alvo', 'sala-102', ENC_B);
    const resp = await request(app).post(`/atividades/${alvo}/inscricoes`).set('X-Usuario', 'p-joao');
    expect(resp.status).toBe(409);
    expect(resp.body.erro).toBe('CONFLITO_DE_HORARIO');
  });

  it('cancelada não bloqueia inscrição sobreposta (201)', async () => {
    await request(app).post('/_teste/reset').expect(204);
    const a = await criar(app, 'A', 'sala-101', ENC_A);
    const ins = await request(app).post(`/atividades/${a}/inscricoes`).set('X-Usuario', 'p-carla').expect(201);
    await request(app).post(`/inscricoes/${ins.body.id}/cancelamento`).set('X-Usuario', 'p-carla').expect(200);
    const b = await criar(app, 'B', 'sala-102', ENC_B);
    await request(app).post(`/atividades/${b}/inscricoes`).set('X-Usuario', 'p-carla').expect(201);
  });

  it('expirada não bloqueia inscrição sobreposta (201)', async () => {
    await request(app).post('/_teste/reset').expect(204);
    const lotada = await criar(app, 'Lotada', 'lab-3', ENC_A, 1);
    await request(app).put('/_teste/relogio').send({ agora: '2026-10-13T10:00:00-03:00' }).expect(200);
    const conf = await request(app).post(`/atividades/${lotada}/inscricoes`).set('X-Usuario', 'p-carla').expect(201);
    const espera = await request(app).post(`/atividades/${lotada}/inscricoes`).set('X-Usuario', 'p-joao').expect(201);
    await request(app).post(`/inscricoes/${conf.body.id}/cancelamento`).set('X-Usuario', 'p-carla').expect(200);
    await request(app).put('/_teste/relogio').send({ agora: '2026-10-13T12:01:00-03:00' }).expect(200);
    await request(app).post(`/inscricoes/${espera.body.id}/confirmacao`).set('X-Usuario', 'p-joao').expect(422);
    const alvo = await criar(app, 'Alvo', 'sala-102', ENC_B);
    await request(app).post(`/atividades/${alvo}/inscricoes`).set('X-Usuario', 'p-joao').expect(201);
  });
});

process.env.MODO_TESTE = '1';
const request = require('supertest');
const { criarServidor } = require('../src/app');

// Ponto 4 (RN-208): em_espera não conta, convocada conta, palestra não entra.
// Origem: entrevistas/M2-inscricoes.mc P6; spec RN-208.
describe('M2-RN-208 — contagem do limite de 3 minicursos', () => {
  let app;
  beforeEach(() => { app = criarServidor(); });

  const SLOTS = [
    ['08:00:00', '10:00:00'],
    ['11:00:00', '13:00:00'],
    ['14:00:00', '16:00:00'],
    ['17:00:00', '18:00:00'],
    ['18:30:00', '19:30:00'],
  ];
  const SALAS = ['sala-101', 'sala-102', 'lab-3', 'auditorio', 'sala-101'];

  async function criarMini(app, titulo, i, vagas = 20) {
    const r = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
      titulo, tipo: 'minicurso', salaId: SALAS[i % SALAS.length], vagas,
      encontros: [
        { inicio: `2026-10-19T${SLOTS[i][0]}-03:00`, fim: `2026-10-19T${SLOTS[i][1]}-03:00` },
        { inicio: `2026-10-20T${SLOTS[i][0]}-03:00`, fim: `2026-10-20T${SLOTS[i][1]}-03:00` },
      ]
    });
    expect(r.status).toBe(201);
    return r.body.id;
  }

  async function criarPalestra(app, titulo, i) {
    const r = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
      titulo, tipo: 'palestra', salaId: SALAS[i % SALAS.length], vagas: 20,
      encontros: [
        { inicio: `2026-10-2${1 + (i % 3)}T${SLOTS[i][0]}-03:00`, fim: `2026-10-2${1 + (i % 3)}T${SLOTS[i][1]}-03:00` },
      ]
    });
    expect(r.status).toBe(201);
    return r.body.id;
  }

